class IDALineTypes(object):
    signal = "D"
    signalField = "M"
    dataType = "S"
    dataTypeField = "F"
    constant = "C"


class TypeTag(object):
    TT_UINT8 = 0
    TT_INT8 = 1
    TT_UINT16 = 2
    TT_INT16 = 3
    TT_UINT32 = 4
    TT_INT32 = 5
    TT_REAL = 7
    TT_DOUBLEREAL = 9
    TT_BOOL = 10
    TT_ARRAY = 14
    TT_POINTER = 15
    TT_STRUCT = 17
    TT_UNION = 18
    TT_SIGNAL = 23
    TT_UINT64 = 26
    TT_INT64 = 27


class AdditionalTagInfo(object):
    TI_NONE = 0
    TI_ENUM = 1
    TI_ENUM_VAL = 2
    TI_RANGE = 3
    TI_NEAR = 4
    TI_FAR = 5
    TI_PACKED = 6
    TI_CONSTANT = 7


class IDATypesDatLine(object):
    """
    <row>       running row number of this row in this file
    <lt>        line type
                constant = 'C';
                signal = 'D';
                signalField = 'M';
                dataType = 'S';
                dataTypeField = 'F';

    <tn>        type name
                when <lt> equals S/F/C              type name
                when <lt> equals M/D                message number in hex
    <fn>        field name
    <ftn>       field type name or message name
    <tag>       type tag
                Tags marked with X are currently in use.
                TT_UINT8         = 0,   // X
                TT_INT8          = 1,   // X
                TT_UINT16        = 2,   // X
                TT_INT16         = 3,   // X
                TT_UINT32        = 4,   // X
                TT_INT32         = 5,   // X
                TT_RESERVED      = 6,   //
                TT_REAL          = 7,   // X
                TT_RESERVED2     = 8,   //
                TT_DOUBLEREAL    = 9,   // X
                TT_LASTNUM       = 9,   //    Last numeric type tag, same value
                                              as previous line

                TT_BOOL          = 10,  // X
                TT_CHARACTER     = 11,  // X
                TT_TIME          = 12,  // X
                TT_PID           = 13,  // X
                TT_LASTSIMPRED   = 13,  //    Last simple predefined type tag

                TT_ARRAY         = 14,  // X
                TT_POINTER       = 15,  // X
                TT_NIL_POINTER   = 16,  //    Polymorphic nil pointer
                TT_STRUCT        = 17,  // X
                TT_UNION         = 18,  // X
                TT_BITSTRUCT     = 19,  //    Obsolete
                TT_FUNCTION      = 20,  //    Function or operator
                TT_PROCEDURE     = 21,  //    TNSDL procedure
                TT_PROCESS       = 22,  //    TNSDL process
                TT_SIGNAL        = 23,  // X
                TT_TIMER         = 24,  //
                TT_ALARM         = 25,  //
                TT_UINT64        = 26,  // X
                TT_INT64         = 27,  // X

                TT__LAST         = 27,

                TT_PSEUDOTYPE    = 50,  // X  Usually the void pointer returned
                                              by functions.
                                              Also used for an unknown type in
                                              a structure for example. I.e. it
                                              usually means 'the type is
                                              unknown'.
    <ti>        additional tag information
                TI_NONE          = 0
                TI_ENUM          = 1
                TI_ENUM_VAL      = 2
                TI_RANGE         = 3
                TI_NEAR          = 4
                TI_FAR           = 5
                TI_PACKED        = 6
                TI_CONSTANT      = 7
    <off>       field offset in the substructure
    <siz>       field size / type size
    <bsz>       type size in bits in a packed structure
            This is only used for RANGE and ENUM types. The TESTP file provides additional information
            about the number of bits needed to represent these types in a packed structure. BSZ is used for this value.
            See the TESTP documentation for more information in the bit size.
    <v1>        various data 1
            If TAG == TT_STRUCT/TT_UNION/TT_SIGNAL:
               V1 = count of fields where LVL = current LVL + 1
               V2 = count of fields where LVL > current LVL

            If TAG == TT_ARRAY:
               V1 = count of indexes in array (array dimension)

            If TI == TI_ENUM:
               V1 = count of enums

            If TI == TI_ENUM_VAL:
               V1 = actual enum value
               V2 = index of enum value (starting from zero)

            If TI == TI_RANGE:
               V1 = range start
               V2 = range end

            If TI == TI_CONSTANT:
               If TAG == TI_ARRAY or TI_CHARACTER
                 V1 = length of character constant
               else
                 V1  = numerical constant value
                 TAG = smallest type the constant will fit in
    <v2>        various data 2
            See above.
    <con>       specifies whether this data type has constants
            If SUB == true:
               CON == true -> The sub data type contains constants

            If SUB == false:
               CON > 0 -> Count of constants in this data type. i.e. there are
               constants declared in the current data type.
    <var>       specifies whether this type has encode/decode operations
            For types:
               If TRUE then the types has the 'ensize' operator defined and
               hence the size of the type is probably variable.  Offsets (OFF)
               can stil be used though. SIZ is the maximum size of the type.

            For signals:
               If TRUE then the signal has encode/decode operators. In this
               case the size is probably variable and SIZ is invalid (zero).
               Offsets (OFF) can still be used though.
    <lvl>       level in the type hierarchy
    <sub>       specifies whether this field or type is constructed of another type
    <fix>       index to the file table
    <fln>       line number in the file where this definition can be found
    <com>       optional comment
    """

    IDALine = namedtuple(
        "IDALine",
        "row lt tn fn ftn tag ti off siz bsz v1 v2 con var lvl sub fix fln com",
    )

    def __new__(cls, *args):
        return IDATypesDatLine.IDALine(*IDATypesDatLine.parse_arguments(args))

    @staticmethod
    def parse_arguments(args):
        """to be created"""
        (
            row,
            lt,
            tn,
            fn,
            ftn,
            tag,
            ti,
            off,
            siz,
            bsz,
            v1,
            v2,
            con,
            var,
            lvl,
            sub,
            fix,
            fln,
            com,
        ) = args
        return (
            int(row),
            lt,
            tn,
            fn,
            ftn,
            int(tag),
            int(ti),
            int(off),
            int(siz),
            int(bsz),
            int(v1),
            int(v2),
            int(con),
            int(var),
            int(lvl),
            int(sub),
            int(fix),
            int(fln),
            com.strip('"'),
        )


class AaTraceMessage(Tree):
    """
    Contains aatrace message structure, which can be printed or parsed into real message using bytes.
    To parser a message it is not required its bytes to be exact length.

    PROBLEMS:
    When parsing, messsage is created as dictionary. There are same message definitions (in types.dat file)
    that have same field names repeated, for example:

    ...
    28659,D,2382,,TRSW_SEND_IPCS_REQ_MSG,23,0,0,22876,0,6,7,0,0,0,1,0,0,""
    28660,M,2382,msgHeader,SMessageHeader,17,0,0,16,0,5,0,0,0,1,1,0,37,""
    28661,M,2382,msgHeader,STrswMsgHeader,17,0,16,12,0,3,0,0,0,1,1,0,16900,""
    28662,M,2382,hasUniqueParam,TBoolean,4,0,28,4,0,0,0,0,0,1,1,0,444,""
    ...

    Two 'msgHeader' fields are present - IMHO this will not be a problem with whole message, like other fields will have
    invalid values etc., but it will cause first field to be deleted from dictionary.
    """

    ROOT_DEF_LINE = r"(^\d+,D,(.*?),,(.*?),.*?$)"

    def add_field(self, field, parent=None):
        """to be created"""
        if field.field_name:
            super(AaTraceMessage, self).add_node(field, parent)

    def parse(self, bytes=None):
        """to be created"""
        root = self.get_node(nid=self.root)
        if not bytes:
            return self.to_dict()

        # if len(root) * 2 != len(bytes):
        # raise WrongByteLength(msg_name=root.field_name, expected_len=len(root) * 2, actual_len=len(bytes))

        # self._fill(root, bytes)
        root._fill(bytes, self)

        msg_dict = self.to_dict()
        return Message(msg_dict, {})
        # return msg_dict

    def to_dict(self):
        """to be created"""
        root = self.get_node(nid=self.root)
        return {root.field_name: self._to_dict(root)}

    def _to_dict(self, parent):
        if isinstance(parent, Array):
            return [child._value for child in self._get_children(parent)]
        elif isinstance(parent, (Signal, Struct, Union)):
            return self._create_subdict(parent)
        else:
            return parent._value

    def _create_subdict(self, node):
        d = {}
        for child in self._get_children(node):
            if isinstance(child, Array):
                d[child.field_name] = [
                    self._to_dict(item) for item in self._get_children(child)
                ]
            elif isinstance(child, (Struct, Union)):
                d[child.field_name] = self._to_dict(child)
            else:
                d[child.field_name] = child._value
        return d

    def _get_children(self, parent):
        return [
            self.get_node(nid=child_id)
            for child_id in parent.successors(parent._initial_tree_id)
        ]


class Field(Node):
    order_index = 0

    def __init__(self, field_definition):
        self.row_number = field_definition.row
        self.line_type = field_definition.lt
        self.type_name = field_definition.tn
        self.field_name = field_definition.fn
        self.field_type_name_or_msg_name = field_definition.ftn
        self.type_tag = field_definition.tag
        self.addition_tag_info = field_definition.ti
        self.field_offset = field_definition.off
        self.field_or_type_size = field_definition.siz
        self.type_bit_size = field_definition.bsz
        self.var_1 = field_definition.v1
        self.var_2 = field_definition.v2
        self.has_constraints = field_definition.con
        self.has_encode_decode_operations = field_definition.var
        self.level = field_definition.lvl
        self.is_constructed = field_definition.sub
        self.file_table_index = field_definition.fix
        self.definition_line_number = field_definition.fln
        self.comment = field_definition.com
        super(Field, self).__init__(
            tag=(
                self.field_name if self.field_name else self.field_type_name_or_msg_name
            ),
            identifier=id(self),
            data=self,
        )
        self._value = None
        self._order_index = self._next_order_index()
        self._orig_defs = field_definition

    def has_subfields(self):
        """to be created"""
        if self.var_1:
            return True
        return False

    def has_children(self):
        """to be created"""
        if self.successors(self._initial_tree_id):
            return True
        return False

    def _fill(self, bytes, message):
        for child in message._get_children(self):
            if isinstance(child, Array):
                child._fill(bytes, message)
                continue
            start_byte = child.field_offset * 2
            end_byte = start_byte + child.field_or_type_size * 2
            if child.has_children():
                child._fill(bytes[start_byte:end_byte], message)
            else:
                child._value = bytes[start_byte:end_byte]

    def _next_order_index(self):
        Field.order_index += 1
        return Field.order_index

    def __lt__(self, other):
        return self._order_index < other._order_index

    def __len__(self):
        return self.field_or_type_size

    def __repr__(self):
        return str(self._orig_defs)

    @property
    def details(self):
        """to be created"""
        return "{field_name} [start_byte: {start_byte}; length: {length}]".format(
            field_name=self.field_name,
            start_byte=self.field_offset,
            length=self.field_or_type_size,
        )

    @property
    def filled(self):
        """to be created"""
        if self._value:
            return "{field_name}: {value}".format(
                field_name=self.field_name, value=self._value
            )
        return "{field_name}".format(field_name=self.field_name)


class Signal(Field):
    def __init__(self, field_definition):
        super(Signal, self).__init__(field_definition)
        self.definition_line_number = self.row_number
        self.field_name = self.field_type_name_or_msg_name


class Number(Field):
    pass


class Boolean(Number):
    pass


class Struct(Field):
    pass


class Array(Field):
    @property
    def filled(self):
        """to be created"""
        return "{field_name}[{size}]".format(
            field_name=self.field_name, size=self.var_1
        )


class Enum(Field):
    pass


class Union(Field):
    pass


class Pointer(Field):
    pass


class EmilParser(object):
    def __init__(self, messages_definition=None):
        self.msg_def = []
        self.hex_id__root_line = {}
        self.msg_name__root_line = {}
        if messages_definition:
            self.load_messages_definition(messages_definition)

    def create_message_structure_from_definition(self, msg_name=None, hex_id=None):
        """to be created"""
        self._check_if_messages_definition_are_loaded_and_raise_if_not()
        if msg_name:
            root_def = self._get_root_def(msg_name=msg_name)
        else:
            root_def = self._get_root_def(hex_id=hex_id)
        root_field = _field_factory(root_def)
        message = AaTraceMessage()
        message.add_field(root_field)
        if root_field.has_subfields():
            self._create_substructure(message, root_field)
        return message

    def get_message_name_from_bytes(self, bytes, raise_on_not_found=True):
        """to be created"""
        self._check_if_messages_definition_are_loaded_and_raise_if_not()
        hex_id = bytes[2 * 2: 4 * 2]
        root_def = self._get_root_def(
            hex_id=hex_id, raise_on_not_found=raise_on_not_found
        )
        if not root_def:
            return None
        root_field = _field_factory(root_def)
        return root_field.field_name

    def get_message_name_from_hex_id(self, hex_id):
        """to be created"""
        self._check_if_messages_definition_are_loaded_and_raise_if_not()
        root_def = self._get_root_def(hex_id=hex_id, raise_on_not_found=True)
        if not root_def:
            return None
        root_field = _field_factory(root_def)
        return root_field.field_name

    def get_message_hex_id_from_bytes(self, bytes):
        """to be created"""
        return bytes[2 * 2: 4 * 2].upper()

    def get_message_hex_id_from_name(self, msg_name):
        """to be created"""
        self._check_if_messages_definition_are_loaded_and_raise_if_not()
        root_def = self._get_root_def(msg_name=msg_name, raise_on_not_found=True)
        if not root_def:
            return None
        root_field = _field_factory(root_def)
        return root_field.type_name.upper()

    def load_messages_definition(self, messages_definition):
        """to be created"""
        try:
            self.msg_def = [
                IDATypesDatLine(*ida_sack_line.split(",", 18))
                for ida_sack_line in messages_definition.splitlines()
            ]
        except ValueError:
            raise InvalidMessageDefinition("Check if definitions are in valid format")
        self.hex_id__root_line = {
            ida_line.tn: ida_line.row
            for ida_line in self.msg_def
            if ida_line.lt == IDALineTypes.signal
        }
        self.msg_name__root_line = {
            ida_line.ftn: ida_line.row
            for ida_line in self.msg_def
            if ida_line.lt == IDALineTypes.signal
        }

    def is_messages_definition_loaded(self):
        """to be created"""
        if self.msg_def:
            return True
        return False

    def _create_substructure(self, msg, parent):
        original_field_parent = parent

        parent = self._create_new_parent(original_field_parent)

        previous_field = None
        for field_index in range(1, parent.var_2 + 1):
            next_field_id = parent.definition_line_number + field_index
            field_def = self._get_field_def(row_index=next_field_id)
            current_field = _field_factory(field_def)
            if current_field.line_type == IDALineTypes.constant:
                return
            if isinstance(current_field, Array):
                previous_field = self._create_array_substructure(
                    current_field, field_def, msg, original_field_parent, previous_field
                )
            elif isinstance(current_field, (Struct, Union)):
                self._create_struct_substructure(
                    field_def, msg, original_field_parent, previous_field
                )
                previous_field = None
            else:
                self._create_scalar_substructure(
                    field_def, msg, original_field_parent, previous_field
                )
                previous_field = None

    def _create_scalar_substructure(
        self, field_def, msg, original_field_parent, previous_field
    ):
        if isinstance(previous_field, Array):
            prev_field = previous_field
            msg.add_field(prev_field, parent=original_field_parent)
            for array_index in range(previous_field.var_1):
                self._create_subfield(array_index, field_def, msg, prev_field)
        else:
            field = _field_factory(field_def)
            msg.add_field(field, parent=original_field_parent)

    def _create_subfield(self, array_index, field_def, msg, prev_field):
        array_subfield = _field_factory(field_def)
        array_subfield.field_offset = (
            prev_field.field_offset + array_index * array_subfield.field_or_type_size
        )
        msg.add_field(array_subfield, parent=prev_field)
        return array_subfield

    def _create_struct_substructure(
        self, field_def, msg, original_field_parent, previous_field
    ):
        if isinstance(previous_field, Array):
            prev_field = previous_field
            msg.add_field(prev_field, parent=original_field_parent)
            for array_index in range(prev_field.var_1):
                array_subfield = self._create_subfield(
                    array_index, field_def, msg, prev_field
                )
                self._create_substructure(msg, array_subfield)
        else:
            field = _field_factory(field_def)
            msg.add_field(field, parent=original_field_parent)
            self._create_substructure(msg, field)

    def _create_array_substructure(
        self, current_field, field_def, msg, original_field_parent, previous_field
    ):
        if isinstance(previous_field, Array):
            self._create_array_of_arrays(
                current_field, field_def, msg, original_field_parent, previous_field
            )
            return
        if (
            not current_field.field_name
            and not current_field.field_type_name_or_msg_name
        ):
            return
        elif current_field.field_name and not current_field.field_type_name_or_msg_name:
            return _field_factory(field_def)
        elif current_field.field_name and current_field.field_type_name_or_msg_name:
            field = _field_factory(field_def)
            msg.add_field(field, parent=original_field_parent)
            self._add_elemtents_to_array(
                field,
                msg,
                start_offset=field.field_offset,
                top_array_index=0,
                top_element_size=0,
            )

    def _create_array_of_arrays(
        self, current_field, field_def, msg, original_field_parent, previous_field
    ):
        if current_field.field_name == previous_field.field_name:
            top_array_def = self._get_field_def(row_index=previous_field.row_number)
            top_array_field = _field_factory(top_array_def)
            msg.add_field(top_array_field, parent=original_field_parent)
            top_element_size = int(
                top_array_field.field_or_type_size / top_array_field.var_1
            )
            for top_array_index in range(previous_field.var_1):
                field = _field_factory(field_def)
                msg.add_field(field, parent=top_array_field)
                self._add_elemtents_to_array(
                    field,
                    msg,
                    start_offset=top_array_field.field_offset,
                    top_array_index=top_array_index,
                    top_element_size=top_element_size,
                )

    def _add_elemtents_to_array(
        self, field, msg, start_offset, top_array_index, top_element_size
    ):
        element_size = int(field.field_or_type_size / field.var_1)
        array_subfield_def = self._create_array_subfield(field)
        for array_index in range(field.var_1):
            array_element = _field_factory(array_subfield_def)
            array_element.field_offset = (
                start_offset
                + array_index * element_size
                + top_array_index * top_element_size
            )
            msg.add_field(array_element, parent=field)

    def _create_array_subfield(self, field):
        array_subfield_def = self._get_field_def(
            row_index=field.definition_line_number + 1
        )
        array_subfield_def_dict = array_subfield_def._asdict()
        array_subfield_def_dict["fn"] = field.field_name
        array_subfield_def = IDATypesDatLine(*array_subfield_def_dict.values())
        return array_subfield_def

    def _create_new_parent(self, original_parent):
        if not original_parent.is_root():
            new_parent_definition = self._get_field_def(
                row_index=original_parent.definition_line_number
            )
            new_parent = _field_factory(new_parent_definition)
            new_parent.definition_line_number = original_parent.definition_line_number
            return new_parent
        return original_parent

    def _get_root_def(self, msg_name=None, hex_id=None, raise_on_not_found=True):
        if msg_name:
            return self._get_root_def_by_msg_name(msg_name, raise_on_not_found)
        elif hex_id:
            return self._get_root_def_by_hex_id(hex_id, raise_on_not_found)
        else:
            raise ValueError("One of fields 'msg_name' or 'hex_id' must be specified")

    def _get_root_def_by_msg_name(self, msg_name, raise_on_not_found):
        if not isinstance(msg_name, six.string_types):
            raise TypeError(
                "Wrong root field msg_name '%s' type: %s. String required"
                % (msg_name, type(msg_name))
            )
        try:
            return self.msg_def[self.msg_name__root_line[msg_name.upper()]]
        except KeyError:
            if raise_on_not_found:
                raise RootFieldDefinitionNotFound("Name: %s" % msg_name)

    def _get_root_def_by_hex_id(self, hex_id, raise_on_not_found):
        if not isinstance(hex_id, six.string_types):
            raise TypeError(
                "Wrong root field hex_id '%s' type: %s. String required"
                % (hex_id, type(hex_id))
            )
        try:
            return self.msg_def[self.hex_id__root_line[hex_id.upper()]]
        except KeyError:
            if raise_on_not_found:
                raise RootFieldDefinitionNotFound("Hex id: %s" % hex_id)

    def _get_field_def(self, row_index):
        try:
            return self.msg_def[row_index]
        except IndexError:
            raise FieldDefinitionNotFound("Field row index: %s" % row_index)

    def _check_if_messages_definition_are_loaded_and_raise_if_not(self):
        if not self.is_messages_definition_loaded():
            raise NoMessageDefinitionLoaded


def _field_factory(field_definition):
    field_tag_to_class = {
        TypeTag.TT_SIGNAL: Signal,
        TypeTag.TT_UINT8: Number,
        TypeTag.TT_INT8: Number,
        TypeTag.TT_UINT16: Number,
        TypeTag.TT_INT16: Number,
        TypeTag.TT_UINT32: Number,
        TypeTag.TT_INT32: Number,
        TypeTag.TT_REAL: Number,
        TypeTag.TT_DOUBLEREAL: Number,
        TypeTag.TT_UINT64: Number,
        TypeTag.TT_INT64: Number,
        TypeTag.TT_BOOL: Boolean,
        TypeTag.TT_ARRAY: Array,
        TypeTag.TT_STRUCT: Struct,
        TypeTag.TT_UNION: Union,
        TypeTag.TT_POINTER: Pointer,
    }

    try:
        field_class = field_tag_to_class[field_definition.tag]
    except KeyError:
        raise FieldTagNotSupported("{}".format(field_definition))

    if field_class == Signal:
        Field.order_index = 0
    return field_class(field_definition)
